/* @lc app=leetcode id=3849 lang=kotlin */ class Solution { fun maximumXor(s: String, t: String): String = s.fold(Triple(t.count { it == '1' }, t.count { it == '0' }, StringBuilder())) { (ones, zeros, sb), c -> if (c == '0') (if (ones > 0) Triple(ones - 1, zeros, sb.append('1')) else Triple(ones, zeros - 1, sb.append('0'))) else (if (zeros > 0) Triple(ones, zeros - 1, sb.append('1')) else Triple(ones - 1, zeros, sb.append('0'))) }.third.toString() }